import{_ as a,o as r,c as o,a6 as i}from"./chunks/framework.DNkVJs23.js";const f=JSON.parse('{"title":"Informazioni su Sapphire Star Codex","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/it/others/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/it/others/"}],["meta",{"property":"og:title","content":"Informazioni su Sapphire Star Codex | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Dati di Monster Hunter e ricerca di set per Wilds, Rise con Sunbreak e World con Iceborne."}]]},"headers":[],"relativePath":"it/others/index.md","filePath":"it/others/index.md"}'),t={name:"it/others/index.md"};function n(l,e,d,s,p,c){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="informazioni-su-sapphire-star-codex" tabindex="-1">Informazioni su Sapphire Star Codex <a class="header-anchor" href="#informazioni-su-sapphire-star-codex" aria-label="Permalink to &quot;Informazioni su Sapphire Star Codex&quot;">​</a></h1><h2 id="il-progetto" tabindex="-1">Il progetto <a class="header-anchor" href="#il-progetto" aria-label="Permalink to &quot;Il progetto&quot;">​</a></h2><p>Sapphire Star Codex offre dati di Monster Hunter e ricerca di set di armature. È sviluppata e mantenuta indipendentemente dall’autore di <a href="https://eurekaffeine.github.io/pocket-gallery/" target="_blank" rel="noreferrer">Pocket Gallery</a>. L’app è gratuita, senza pubblicità né funzioni a pagamento.</p><p>Android è disponibile su <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a> e HarmonyOS su <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. La versione iOS è in preparazione. Consulta la sezione <a href="./../#download">download</a>; la disponibilità varia per regione e dispositivo.</p><h2 id="feedback-e-collaborazione" tabindex="-1">Feedback e collaborazione <a class="header-anchor" href="#feedback-e-collaborazione" aria-label="Permalink to &quot;Feedback e collaborazione&quot;">​</a></h2><p>Per segnalare un errore, indica gioco, voce, lingua, passaggi e una fonte verificabile. Nascondi i dati personali nelle schermate. Contatto: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Sono utili anche la condivisione, le correzioni e il <a href="./../support/">sostegno volontario</a>.</p><h2 id="fonti-e-diritti" tabindex="-1">Fonti e diritti <a class="header-anchor" href="#fonti-e-diritti" aria-label="Permalink to &quot;Fonti e diritti&quot;">​</a></h2><p>I dati provengono da <a href="https://docs.wilds.mhdb.io/" target="_blank" rel="noreferrer">MHDB Wilds</a>, <a href="https://mhw-db.com/" target="_blank" rel="noreferrer">MHW DB</a> e file di gioco, con controlli su fonti della comunità. Possono esserci errori o lacune. Nomi, immagini e dati di Monster Hunter appartengono a CAPCOM; le richieste di rimozione saranno rispettate. La licenza MIT del codice adattato da Pocket Gallery non comprende immagini o dati di gioco.</p>',8)])])}const u=a(t,[["render",n]]);export{f as __pageData,u as default};
